export const c12Phy7HtmlOverview = "\n<style>\n  p, li, div:not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  \n  <!-- QUICK GLOSSARY CARD -->\n  <div style=\"background: rgba(224, 64, 251, 0.05); border: 1.5px solid #E040FB; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #E040FB; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary &amp; Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #CE93D8; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Concepts &amp; Key Definitions &bull; Unit VII: Dual Nature of Radiation and Matter</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #E040FB; border-radius: 6px;\">\n        <b style='color: #E040FB; display: block; margin-bottom: 4px;'>1. Work Function (&Phi;<sub>0</sub> / W<sub>0</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Minimum energy required by an electron to escape from a metal surface without any kinetic energy: &Phi;<sub>0</sub> = h &nu;<sub>0</sub> = h c / &lambda;<sub>0</sub> [Electron-volt eV / Joule J, [M<sup>1</sup> L<sup>2</sup> T<sup>-2</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #E040FB; border-radius: 6px;\">\n        <b style='color: #E040FB; display: block; margin-bottom: 4px;'>2. Threshold Frequency (&nu;<sub>0</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Minimum frequency of incident radiation below which no photoelectric emission occurs, regardless of intensity: &nu;<sub>0</sub> = &Phi;<sub>0</sub> / h [Hertz Hz, [M<sup>0</sup> L<sup>0</sup> T<sup>-1</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #E040FB; border-radius: 6px;\">\n        <b style='color: #E040FB; display: block; margin-bottom: 4px;'>3. Stopping Potential (V<sub>0</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Minimum negative retarding potential applied to collector plate at which photoelectric current reduces to exactly zero: e V<sub>0</sub> = K<sub>max</sub> = 1/2 m v<sub>max</sub><sup>2</sup> [Volt V, [M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #E040FB; border-radius: 6px;\">\n        <b style='color: #E040FB; display: block; margin-bottom: 4px;'>4. Photon:</b>\n        <span style=\"color: #FFFFFF;\">Discrete quantum packet of electromagnetic radiation carrying energy E = h&nu; = hc/&lambda; and momentum p = h/&lambda; = E/c, having zero rest mass (m<sub>0</sub> = 0) and traveling at vacuum speed c.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #E040FB; border-radius: 6px;\">\n        <b style='color: #E040FB; display: block; margin-bottom: 4px;'>5. de-Broglie Hypothesis (Matter Waves):</b>\n        <span style=\"color: #FFFFFF;\">Hypothesis that material moving particles (electrons, protons, atoms) exhibit wave properties with de-Broglie wavelength &lambda; = h/p = h/(m v).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #E040FB; border-radius: 6px;\">\n        <b style='color: #E040FB; display: block; margin-bottom: 4px;'>6. Electron Wavelength (&lambda;<sub>e</sub>):</b>\n        <span style=\"color: #FFFFFF;\">de-Broglie wavelength of an electron accelerated through potential difference V volts: &lambda; = 1.227 / &radic;V nm = 12.27 / &radic;V &Aring; [Meter m, [M<sup>0</sup> L<sup>1</sup> T<sup>0</sup>]].</span>\n      </div>\n    </div>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 25px;\">1. Dual Nature of Radiation &amp; Historical Photoelectric Observations</h2>\n<h3 style=\"color: #E040FB; margin-top: 20px;\">(i) Dual Nature of Radiation (Wave vs Particle)</h3>\n<p>Light exhibits a fascinating dual personality in modern physics:</p>\n  <ul>\n    <li>• <b>Wave Nature:</b> Phenomena such as <b>Interference, Diffraction, and Polarization</b> are successfully explained only by treating light as a continuous electromagnetic wave spreading across space.</li>\n    <li>• <b>Particle Nature:</b> Phenomena such as the <b>Photoelectric Effect, Compton Effect, and Blackbody Radiation</b> completely defy classical wave theory and can be explained only by treating light as a stream of discrete energy packets called <b>Photons (or Quanta)</b>.</li>\n  </ul>\n  <p>Light propagates as a wave, but interacts with matter and exchanges energy/momentum as a localized particle!</p>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 1: Dual Nature of Radiation\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.1:</b> Dual Nature of Radiation &ndash; Electromagnetic radiation behaves as continuous propagating waves in space and as localized discrete particle packets (photons) during matter interactions.</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 2: Photoelectric Effect Mechanism\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.2:</b> Photoelectric Effect &ndash; Incident light of suitable threshold frequency (h&nu;) striking a metal surface and instantaneously liberating emitted photoelectrons.</p>\n  </div>\n<h3 style=\"color: #E040FB; margin-top: 25px;\">(ii) Hertz, Hallwachs &amp; Lenard's Experimental Discoveries</h3>\n<ul>\n    <li>• <b>Heinrich Hertz's Observation (1887):</b> While investigating spark discharges across metal electrodes in an LC oscillator, Hertz observed that high-voltage electrical sparks jumped across the gap more easily when the emitter cathode was illuminated with Ultraviolet (UV) light.</li>\n    <li>• <b>Wilhelm Hallwachs' Experiment (1888):</b> Hallwachs connected a clean, uncharged zinc plate to an electroscope. When illuminated with UV light: (i) an uncharged zinc plate became positively charged, (ii) a negatively charged zinc plate rapidly lost its charge, and (iii) a positively charged zinc plate retained its charge. This proved that UV light knocks out <b>negatively charged particles (electrons)</b> from metal surfaces.</li>\n    <li>• <b>Philipp Lenard's Systematic Study (1900):</b> Lenard enclosed two electrodes (emitter cathode C and collector anode A) in an evacuated quartz tube and systematically measured the photocurrent as functions of incident light intensity, frequency, and collector potential.</li>\n  </ul>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 3: Hertz and Lenard's Experimental Observations\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.3:</b> Hertz and Lenard's Observations &ndash; Ultraviolet (UV) light shining on the cathode inside an evacuated tube causes electron emission, creating a measurable electric current registered on the meter.</p>\n  </div>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #CE93D8; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #CE93D8; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: Photoelectric Effect as Vending Machine Coin Mechanism</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Imagine a vending machine that dispenses a soda can (electron) only if you insert a single gold coin worth at least $5 (Threshold energy h&nu;<sub>0</sub>). If you drop 1,000 one-cent copper coins (high intensity, but low frequency &nu; &lt; &nu;<sub>0</sub>), nothing happens because the machine does not accumulate small change. But if you drop a single $10 bill (high frequency &nu; &gt; &nu;<sub>0</sub>), the soda is ejected instantly, and you get $5 back in change as kinetic energy (K<sub>max</sub> = h&nu; - &Phi;<sub>0</sub>)!</div>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 35px;\">2. Experimental Study of Photoelectric Effect &amp; The 4 Fundamental Laws</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 6: Experimental Setup to Study Photoelectric Effect\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.4:</b> Experimental Setup of Photoelectric Effect &ndash; Evacuated tube with photosensitive cathode, collector anode, voltmeter, microammeter, and potential divider to systematically record I-V characteristics.</p>\n  </div>\n<h3 style=\"color: #E040FB; margin-top: 20px;\">(i) Effect of Intensity of Incident Radiation on Photocurrent</h3>\n<p>Keeping the frequency (&nu; &gt; &nu;<sub>0</sub>) and collector potential constant, as the intensity of incident light is increased, the rate of emission of photoelectrons increases in direct proportion.</p>\n  <div style=\"background: rgba(0,0,0,0.3); border-left: 4px solid #76FF03; padding: 10px 14px; border-radius: 6px; margin: 12px 0;\">\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>Photoelectric Current (I) &prop; Intensity of Incident Light</b></span>\n  </div>\n<h3 style=\"color: #E040FB; margin-top: 25px;\">(ii) Effect of Potential &amp; Stopping Potential (V_0)</h3>\n<p>When collector anode A is made positive relative to cathode C, electrons are attracted and current rises to a constant <b>Saturation Current (I<sub>sat</sub>)</b> when all emitted photoelectrons reach anode. When collector is made increasingly negative (retarding potential), photocurrent decreases until at a specific negative potential <b>-V<sub>0</sub></b> called the <b>Stopping Potential (or Cut-off Potential)</b>, the most energetic photoelectrons are repelled and current becomes zero.</p>\n  <div style=\"background: rgba(0,0,0,0.3); border-left: 4px solid #76FF03; padding: 12px 16px; border-radius: 6px; margin: 14px 0;\">\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>K<sub>max</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">2</span></span> m v<sub>max</sub><sup>2</sup> = e V<sub>0</sub></b></span>\n  </div>\n  <p><i>Crucial Finding:</i> <b>Stopping potential V<sub>0</sub> (and K<sub>max</sub>) is completely independent of the intensity of incident radiation</b>! Increasing intensity increases saturation current, but stopping potential remains unchanged.</p>\n<h3 style=\"color: #E040FB; margin-top: 25px;\">(iii) Effect of Frequency on Stopping Potential &amp; Threshold Frequency (&nu;_0)</h3>\n<p>Keeping intensity constant, when incident frequency &nu; is increased, the stopping potential V<sub>0</sub> (and maximum kinetic energy K<sub>max</sub>) increases linearly. Below a characteristic frequency &nu;<sub>0</sub> called <b>Threshold Frequency</b>, no photoelectrons are emitted no matter how intense the light beam is!</p>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 18px 0;\">\n    <b style=\"color: #E040FB; font-size: 16px; display: block; margin-bottom: 10px;\">📜 The 4 Fundamental Experimental Laws of Photoelectric Emission:</b>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 12px; border-left: 3.5px solid #00E5FF; border-radius: 6px;\">\n        <b style=\"color: #00E5FF;\">1. Law of Intensity:</b> For a given photosensitive surface and frequency (&nu; &gt; &nu;<sub>0</sub>), photoelectric current is directly proportional to intensity of incident radiation.\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 12px; border-left: 3.5px solid #38BDF8; border-radius: 6px;\">\n        <b style=\"color: #38BDF8;\">2. Law of Velocity / Energy:</b> Maximum kinetic energy (K<sub>max</sub>) and stopping potential (V<sub>0</sub>) are directly proportional to incident frequency &nu; and completely independent of light intensity.\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 12px; border-left: 3.5px solid #76FF03; border-radius: 6px;\">\n        <b style=\"color: #76FF03;\">3. Law of Threshold Frequency:</b> For every metal surface, there exists a minimum threshold frequency &nu;<sub>0</sub> below which no emission occurs, however intense the incident light.\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 12px; border-left: 3.5px solid #F472B6; border-radius: 6px;\">\n        <b style=\"color: #F472B6;\">4. Law of Instantaneous Emission:</b> Photoelectric emission is instantaneous without any measurable time lag (&Delta;t &lt; 10<sup>-9</sup> s or 1 nanosecond) between illumination and electron emission.\n      </div>\n    </div>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 35px;\">3. Einstein's Photoelectric Equation &amp; Particle Nature of Light</h2>\n<h3 style=\"color: #E040FB; margin-top: 20px;\">(i) Einstein's Quantum Formulation (Nobel Prize 1921)</h3>\n<p>In 1905, Albert Einstein explained the photoelectric effect by proposing that light propagates not as continuous wave fronts, but as discrete quanta of energy called <b>Photons</b>. When a photon of energy E = h&nu; collides with a conduction electron on a metal surface:</p>\n  <ul>\n    <li>• A part of the photon energy is used to liberate the electron against the metal surface barrier, equal to the <b>Work Function &Phi;<sub>0</sub> = h&nu;<sub>0</sub></b>.</li>\n    <li>• The remaining energy is imparted to the ejected photoelectron as its <b>Maximum Kinetic Energy (K<sub>max</sub>)</b>.</li>\n  </ul>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 4: Einstein's Photoelectric Equation\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.5:</b> Einstein's Photoelectric Equation &ndash; Energy Conservation: h&nu; = &Phi; + K<sub>max</sub> (where h&nu; is photon energy, &Phi; is work function, and K<sub>max</sub> is photoelectron kinetic energy).</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(224, 64, 251, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #E040FB; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(224, 64, 251, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Einstein's Photoelectric Equation &amp; Graphical Slope (h/e)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Conservation of Energy):</b><br>\n    Energy of Incident Photon = Work Function + Maximum Kinetic Energy of Electron<br>\n    h &nu; = &Phi;<sub>0</sub> + K<sub>max</sub> &rArr; <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>K<sub>max</sub> = h &nu; - &Phi;<sub>0</sub></b></span>.<br>\n    <b>Step 2 (Expressing Work Function as &Phi;<sub>0</sub> = h &nu;<sub>0</sub> = h c / &lambda;<sub>0</sub>):</b><br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>K<sub>max</sub> = h (&nu; - &nu;<sub>0</sub>) = h c [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;<sub>0</sub></span></span> ]</b></span>.<br>\n    <b>Step 3 (In terms of Stopping Potential V<sub>0</sub> where K<sub>max</sub> = e V<sub>0</sub>):</b><br>\n    e V<sub>0</sub> = h &nu; - &Phi;<sub>0</sub> &rArr; <span style=\"color: #00E5FF; font-family: monospace; font-size: 17px;\"><b>V<sub>0</sub> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">e</span></span>) &nu; - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&Phi;<sub>0</sub></span><span style=\"padding: 0 2px; display: inline-block;\">e</span></span></b></span>.<br>\n    <b>Step 4 (Linear Graph of V<sub>0</sub> vs Frequency &nu;):</b><br>\n    Comparing with straight line equation y = m x + c:<br>\n    • <b>Slope of Graph:</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>Slope = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">e</span></span></b></span> (Universal constant, identical for all metal surfaces!).<br>\n    • <b>X-intercept (V<sub>0</sub> = 0):</b> &nu; = &nu;<sub>0</sub> (Threshold frequency).<br>\n    • <b>Y-intercept (&nu; = 0):</b> - &Phi;<sub>0</sub>/e (Negative intercept equals work function divided by electronic charge).\n  </div>\n  </div>\n  <div style=\"background: rgba(220, 38, 38, 0.1); border: 1.2px solid rgba(239, 68, 68, 0.4); border-left: 5px solid #EF4444; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #F87171; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">⚠️ BOARD EXAM TRAP &amp; CONCEPTUAL PITFALL: Why Did Classical Wave Theory Fail Completely to Explain Photoelectric Effect?</div>\n    <div style=\"color: #FCA5A5; font-size: 14.5px; line-height: 1.6;\">\n    1. <b>Energy vs Intensity:</b> Wave theory predicted electron kinetic energy should increase with intensity. In reality, energy depends strictly on frequency &nu; and is independent of intensity.<br>\n    2. <b>Threshold Frequency:</b> Wave theory predicted light of any frequency with sufficient intensity could eject electrons. In reality, no emission occurs below &nu;<sub>0</sub>.<br>\n    3. <b>Time Lag:</b> Wave energy spreads continuously over the wavefront; calculating energy absorbed per electron atom predicts a delay of hours/days. In reality, emission is instantaneous (&Delta;t &lt; 10<sup>-9</sup> s)!\n  </div>\n  </div>\n<h3 style=\"color: #E040FB; margin-top: 25px;\">(ii) Characteristic Properties of Photons</h3>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 5: Particle Nature of Light (Photons)\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.6:</b> Particle Nature of Light &ndash; Light consists of discrete energy packets called photons, each carrying quantized energy E = h&nu; and momentum p = h/&lambda;.</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <ul style=\"margin-left: 20px; line-height: 1.85;\">\n      <li>1. <b>Energy:</b> Each photon carries discrete quantum energy: <span style=\"color: #76FF03;\"><b>E = h &nu; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h c</span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;</span></span></b></span>.</li>\n      <li>2. <b>Momentum:</b> Photons carry linear momentum: <span style=\"color: #76FF03;\"><b>p = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">E</span><span style=\"padding: 0 2px; display: inline-block;\">c</span></span></b></span>.</li>\n      <li>3. <b>Rest Mass:</b> The rest mass of a photon is <b>strictly zero (m<sub>0</sub> = 0)</b>. A photon cannot exist at rest.</li>\n      <li>4. <b>Universal Velocity:</b> All photons travel in vacuum with the identical speed of light: <b>c = 3 &times; 10<sup>8</sup> m/s</b>.</li>\n      <li>5. <b>Electrical Neutrality:</b> Photons are electrically neutral and are <b>not deflected by electric or magnetic fields</b>.</li>\n      <li>6. <b>Photon-Particle Collisions:</b> In photon-electron collisions, total energy and total momentum are conserved, but the number of photons may not be conserved (photon may be absorbed or created).</li>\n    </ul>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 35px;\">4. Matter Waves &amp; Wave Nature of Particles (de-Broglie Hypothesis)</h2>\n<h3 style=\"color: #E040FB; margin-top: 20px;\">(i) The de-Broglie Hypothesis (1924)</h3>\n<p>French physicist <b>Louis de-Broglie</b> proposed a revolutionary symmetry argument: Nature loves symmetry. If electromagnetic radiation possesses dual wave-particle character, then material particles (electrons, protons, neutrons, atoms) in motion must also exhibit wave-like properties. Waves associated with moving particles are called <b>Matter Waves (or de-Broglie Waves)</b>.</p>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 7: Matter Waves &ndash; Wave Nature of Moving Particles\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.7:</b> Matter Waves &ndash; According to de-Broglie, every moving material particle of momentum p has an associated wave of de-Broglie wavelength &lambda; = h/p.</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(224, 64, 251, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 360px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 8: de-Broglie Relation for Electrons &amp; Microscopic Particles\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 7.8:</b> de-Broglie Relation for Electrons &ndash; Quantum wave propagation of electrons with wavelength &lambda; = h/p = h/(mv).</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(224, 64, 251, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #E040FB; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(224, 64, 251, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: de-Broglie Wavelength Formulas for Particles &amp; Accelerated Electrons</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Basic Formulation from Photon Energy Equivalence):</b><br>\n    For a photon: E = h &nu; = h c / &lambda; and E = m c<sup>2</sup>.<br>\n    m c<sup>2</sup> = h c / &lambda; &rArr; &lambda; = h / (m c) = h / p.<br>\n    By de-Broglie hypothesis, for any material particle of mass m moving with velocity v:<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">p</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">m v</span></span></b></span>.<br>\n    <b>Step 2 (In Terms of Kinetic Energy E<sub>k</sub>):</b><br>\n    Kinetic Energy E<sub>k</sub> = p<sup>2</sup> / (2m) &rArr; p = &radic;(2 m E<sub>k</sub>).<br>\n    <span style=\"color: #00E5FF; font-family: monospace; font-size: 16.5px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;(2 m E<sub>k</sub>)</span></span></b></span>.<br>\n    <b>Step 3 (For a Charged Particle q Accelerated Through Potential V):</b><br>\n    E<sub>k</sub> = q V &rArr; <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;(2 m q V)</span></span></b></span>.<br>\n    <b>Step 4 (Special Case: Accelerated Electron):</b><br>\n    Substituting m<sub>e</sub> = 9.11 &times; 10<sup>-31</sup> kg, e = 1.6 &times; 10<sup>-19</sup> C, h = 6.63 &times; 10<sup>-34</sup> J s:<br>\n    &lambda;<sub>e</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">6.63 &times; 10<sup>-34</sup></span><span style=\"padding: 0 2px; display: inline-block;\">&radic;[2 &times; (9.11 &times; 10<sup>-31</sup>) &times; (1.6 &times; 10<sup>-19</sup>) &times; V]</span></span> = <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1.227</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;V</span></span> nm = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">12.27</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;V</span></span> &Aring;</b></span>.<br>\n    <b>Step 5 (Thermal Neutrons / Gas Molecules at Temperature T):</b><br>\n    Average thermal kinetic energy E = 3/2 k<sub>B</sub> T &rArr; <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;(3 m k<sub>B</sub> T)</span></span></b></span>.\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(224, 64, 251, 0.4); border-left: 5px solid #E040FB; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #E040FB; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: de-Broglie Wavelength (&lambda; = h/p)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Wavelength of the matter wave associated with any moving material particle possessing linear momentum p = mv.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">Meter (m)</span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>0</sup> L<sup>1</sup> T<sup>0</sup>]</span></span>\n    </div>\n  </div>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #CE93D8; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #CE93D8; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: Why Don't We See Waves for a Moving Cricket Ball?</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">A cricket ball of mass m = 0.15 kg bowled at v = 30 m/s has momentum p = 4.5 kg m/s. Its de-Broglie wavelength is &lambda; = h/p = (6.63 &times; 10<sup>-34</sup>)/4.5 &approx; 1.5 &times; 10<sup>-34</sup> m. This wavelength is trillions of times smaller than an atomic nucleus (~10<sup>-15</sup> m), making macroscopic wave effects impossible to observe. For a light electron (m ~ 10<sup>-30</sup> kg), &lambda; ~ 1 &Aring; (comparable to atomic crystal lattice spacing), producing sharp diffraction!</div>\n  </div>\n  <div style=\"background: rgba(224, 64, 251, 0.08); border: 1.5px solid #E040FB; border-radius: 12px; padding: 20px; margin-top: 35px;\">\n    <h3 style=\"color: #E040FB; margin-top: 0; font-size: 18px; font-weight: bold; text-align: center;\">⚡ Master Revision Formula Cheat Sheet &bull; Unit VII: Dual Nature</h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; margin-top: 14px; font-size: 14.5px;\">\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Photon Energy:</b> E = h &nu; = h c / &lambda;</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Photon Momentum:</b> p = h / &lambda; = E / c</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Work Function:</b> &Phi;<sub>0</sub> = h &nu;<sub>0</sub> = h c / &lambda;<sub>0</sub></div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Einstein's Equation:</b> K<sub>max</sub> = h &nu; - &Phi;<sub>0</sub> = h(&nu; - &nu;<sub>0</sub>)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Stopping Potential:</b> e V<sub>0</sub> = K<sub>max</sub> = 1/2 m v<sub>max</sub><sup>2</sup></div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>V<sub>0</sub> vs &nu; Slope:</b> Slope = h / e &nbsp;|&nbsp; Intercept = -&Phi;<sub>0</sub>/e</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>de-Broglie Wavelength:</b> &lambda; = h / p = h / (m v)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Particle in Kinetic Energy:</b> &lambda; = h / &radic;(2 m E)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Accelerated Charge:</b> &lambda; = h / &radic;(2 m q V)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Accelerated Electron:</b> &lambda;<sub>e</sub> = 1.227 / &radic;V nm = 12.27 / &radic;V &Aring;</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Thermal Particle:</b> &lambda; = h / &radic;(3 m k<sub>B</sub> T)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Energy Conversion:</b> 1 eV = 1.6 &times; 10<sup>-19</sup> J</div>\n    </div>\n  </div>\n</div>";

export const c12Phy7HtmlSolutions = "\n<style>\n  p, li, div:not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  \n  <div style=\"background: rgba(224, 64, 251, 0.08); border: 1.5px solid #E040FB; border-radius: 10px; padding: 14px 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #E040FB; margin: 0 0 4px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">🎯 Complete 100 Board Solutions &bull; Unit VII: Dual Nature of Radiation &amp; Matter</h2>\n    <p class=\"text-center\" style=\"color: #CE93D8; margin: 0; font-size: 14px; text-align: center !important;\">Section A (Q1–Q40: 1 Mark VSA) &bull; Section B (Q41–Q80: 2 &amp; 3 Marks SA) &bull; Section C (Q81–Q100: 5 Marks LA)</p>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 25px;\">SECTION A: Very Short Answer (VSA) Questions (1 Mark Each &bull; Q1 to Q40)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q1: Define photoelectric effect.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Photoelectric effect is the phenomenon of instantaneous emission of electrons from a metallic surface when exposed to electromagnetic radiation of suitable high frequency (&nu; &ge; &nu;<sub>0</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q2: What is a photoelectron?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      An electron ejected from the surface of a photosensitive material by the absorption of an incident photon of sufficient energy.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q3: Define work function of a metal.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The minimum amount of energy required to just liberate an electron from a metal surface with zero kinetic energy: <b>&Phi;<sub>0</sub> = h&nu;<sub>0</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q4: What is the SI unit of work function?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The SI unit of work function is <b>Joule (J)</b>, but it is commonly expressed in <b>electron-volts (eV)</b> (1 eV = 1.6 &times; 10<sup>-19</sup> J).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q5: Name the alkali metal having the lowest work function.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>Caesium (Cs)</b> has the lowest work function (&Phi;<sub>0</sub> &approx; 2.14 eV), making it highly photosensitive to visible light.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q6: Define threshold frequency of a metal.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Threshold frequency (&nu;<sub>0</sub>) is the minimum frequency of incident radiation below which no photoelectric emission takes place, regardless of light intensity.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q7: Define threshold wavelength of a metal.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Threshold wavelength (&lambda;<sub>0</sub>) is the maximum wavelength of incident radiation above which photoelectric emission cannot occur: <b>&lambda;<sub>0</sub> = c / &nu;<sub>0</sub> = h c / &Phi;<sub>0</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q8: Define stopping potential (cut-off potential).</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Stopping potential (V<sub>0</sub>) is the minimum negative retarding potential applied to the collector anode at which photoelectric current reduces to exactly zero.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q9: Write the relation between maximum kinetic energy of a photoelectron and stopping potential.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The relation is: <b>K<sub>max</sub> = 1/2 m v<sub>max</sub><sup>2</sup> = e V<sub>0</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q10: How does stopping potential change if the intensity of incident light is doubled?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Stopping potential <b>remains strictly unchanged</b> because stopping potential depends only on frequency &nu; of incident light, not on intensity.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q11: How does saturation photocurrent change if the intensity of incident light is doubled?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Saturation photocurrent is <b>doubled</b> because photocurrent is directly proportional to incident light intensity.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q12: Write Einstein's photoelectric equation.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Einstein's photoelectric equation is: <b>K<sub>max</sub> = h &nu; - &Phi;<sub>0</sub> = h (&nu; - &nu;<sub>0</sub>) = e V<sub>0</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q13: What is the rest mass of a photon?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The rest mass of a photon is <b>strictly zero (m<sub>0</sub> = 0)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q14: What is the momentum of a photon of wavelength &lambda;?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The linear momentum of a photon is: <b>p = h / &lambda; = E / c = h &nu; / c</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q15: State the value of Planck's constant in SI units.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Planck's constant: <b>h = 6.63 &times; 10<sup>-34</sup> J s (or kg m<sup>2</sup> s<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q16: What physical quantity is represented by the slope of stopping potential (V_0) versus frequency (&nu;) graph?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The slope of the V<sub>0</sub> vs &nu; graph represents the ratio of Planck's constant to electronic charge: <b>Slope = h / e</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q17: Is the slope of V_0 versus &nu; graph dependent on the nature of the metal surface?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> The slope (h/e) is a universal constant and has the exact same value for all metals.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q18: What does the intercept of V_0 versus &nu; graph on the frequency axis represent?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The X-intercept represents the <b>Threshold Frequency (&nu;<sub>0</sub>)</b> of that metal.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q19: What does the negative intercept of V_0 versus &nu; graph on the potential axis represent?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The Y-intercept represents the negative potential corresponding to work function: <b>- &Phi;<sub>0</sub> / e</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q20: State de-Broglie's hypothesis of matter waves.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Any moving material particle of mass m and velocity v possesses wave properties with a characteristic wavelength: <b>&lambda; = h / p = h / (m v)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q21: Write the formula for de-Broglie wavelength of an electron accelerated through potential V volts.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The formula is: <b>&lambda;<sub>e</sub> = 1.227 / &radic;V nm = 12.27 / &radic;V &Aring;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q22: If the kinetic energy of a free electron is doubled, how does its de-Broglie wavelength change?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Since &lambda; = h / &radic;(2mE), doubling E changes &lambda; to: <b>&lambda;' = &lambda; / &radic;2 &approx; 0.707 &lambda;</b> (decreases by ~29.3%).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q23: Between an electron and a proton having the same kinetic energy, which one has a longer de-Broglie wavelength?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Since &lambda; = h / &radic;(2mE) &prop; 1/&radic;m, the lighter particle has a longer wavelength. Because m<sub>electron</sub> &lt;&lt; m<sub>proton</sub>, the <b>electron has a much longer de-Broglie wavelength</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q24: Between an electron and a proton moving with the same velocity, which one has greater momentum?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Momentum p = m v. Since proton has greater mass (m<sub>p</sub> &approx; 1836 m<sub>e</sub>), the <b>proton has greater momentum</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q25: Between an electron and a proton moving with the same velocity, which one has a shorter de-Broglie wavelength?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Since &lambda; = h/(mv), for equal velocity, &lambda; &prop; 1/m. The heavier <b>proton has a shorter de-Broglie wavelength</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q26: What is the maximum time lag observed in photoelectric emission?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The emission is virtually instantaneous with time lag less than <b>10<sup>-9</sup> seconds (1 nanosecond)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q27: Why is photoelectric emission not possible with infrared light for most metals?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Infrared radiation has a very low frequency (&nu; &lt; &nu;<sub>0</sub>) and low photon energy (E &lt; &Phi;<sub>0</sub>), which is insufficient to overcome the work function.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q28: What is the speed of a photon in vacuum?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      All photons travel in vacuum at the universal speed of light: <b>c = 3.0 &times; 10<sup>8</sup> m/s</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q29: Are photons deflected by electric or magnetic fields?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> Photons are electrically neutral and possess zero electric charge.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q30: What happens to the number of photons emitted per second if the intensity of a monochromatic light source is tripled?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The number of photons emitted per second is <b>tripled</b> (Intensity &prop; number of photons emitted per second).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q31: What happens to the energy of each photon if the intensity of monochromatic light is tripled?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The energy of each photon (E = h&nu;) <b>remains strictly constant</b> because photon energy depends only on frequency.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q32: Write the expression for de-Broglie wavelength of a gas molecule of mass m at absolute temperature T.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The expression is: <b>&lambda; = h / &radic;(3 m k<sub>B</sub> T)</b>, where k<sub>B</sub> is Boltzmann's constant.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q33: Calculate the momentum of a photon of frequency 6 x 10¹⁴ Hz.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      p = h&nu;/c = (6.63 &times; 10<sup>-34</sup> &times; 6 &times; 10<sup>14</sup>) / (3 &times; 10<sup>8</sup>) = <b>1.326 &times; 10<sup>-27</sup> kg m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q34: State one optical phenomenon that proves the particle nature of light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The <b>Photoelectric Effect</b> (or Compton Scattering).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q35: State one optical phenomenon that proves the wave nature of light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>Interference</b> (or Diffraction / Polarization).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q36: Why are alkali metals like sodium and potassium preferred in photoelectric cells?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Alkali metals have low ionization energies and very low work functions (&Phi;<sub>0</sub> ~ 2.2 eV), enabling them to emit photoelectrons even under ordinary visible light.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q37: If the momentum of a particle is doubled, by what factor does its de-Broglie wavelength change?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Since &lambda; = h/p, doubling momentum halves the wavelength: <b>&lambda;' = &lambda; / 2</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q38: Can an electron at rest emit a photon? Why?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> A free electron cannot emit or absorb a photon at rest because conservation of energy and momentum cannot be simultaneously satisfied.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q39: What is the value of 1 eV in Joules?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>1 eV = 1.602 &times; 10<sup>-19</sup> Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q40: Why is matter wave associated with everyday macroscopic moving objects (like a running car) not observable?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Macroscopic objects have large mass (m ~ kg) and large momentum, resulting in a microscopic de-Broglie wavelength (~10<sup>-34</sup> m) which is far too tiny to produce observable diffraction effects.\n    </div>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 35px;\">SECTION B: Short Answer (SA) Questions (2 &amp; 3 Marks Each &bull; Q41 to Q80)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q41: The work function of caesium metal is 2.14 eV. Find: (i) the threshold frequency for caesium, (ii) the threshold wavelength of incident light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &Phi;<sub>0</sub> = 2.14 eV = 2.14 &times; 1.6 &times; 10<sup>-19</sup> J = 3.424 &times; 10<sup>-19</sup> J.<br>(i) Threshold Frequency: <b>&nu;<sub>0</sub> = &Phi;<sub>0</sub> / h = (3.424 &times; 10<sup>-19</sup>) / (6.63 &times; 10<sup>-34</sup>) = 5.16 &times; 10<sup>14</sup> Hz</b>.<br>(ii) Threshold Wavelength: <b>&lambda;<sub>0</sub> = c / &nu;<sub>0</sub> = (3 &times; 10<sup>8</sup>) / (5.16 &times; 10<sup>14</sup>) = 5.81 &times; 10<sup>-7</sup> m = 581 nm = 5810 &Aring;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q42: Monochromatic light of frequency 6.0 x 10¹⁴ Hz is incident on a metal surface. If stopping potential is 0.5 V, calculate the work function of the metal.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &nu; = 6.0 &times; 10<sup>14</sup> Hz, V<sub>0</sub> = 0.5 V &rArr; K<sub>max</sub> = e V<sub>0</sub> = 0.5 eV.<br>Incident Photon Energy: E = h &nu; = (6.63 &times; 10<sup>-34</sup> &times; 6.0 &times; 10<sup>14</sup>) / (1.6 &times; 10<sup>-19</sup>) eV = 3.978 / 1.6 eV = 2.486 eV.<br>Einstein's equation: K<sub>max</sub> = E - &Phi;<sub>0</sub> &rArr; &Phi;<sub>0</sub> = E - K<sub>max</sub> = 2.486 eV - 0.50 eV = <b>1.986 eV &approx; 1.99 eV</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q43: Calculate the de-Broglie wavelength of an electron accelerated through a potential difference of 100 V.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: V = 100 Volts.<br>Formula: &lambda;<sub>e</sub> = 1.227 / &radic;V nm.<br>&lambda;<sub>e</sub> = 1.227 / &radic;100 nm = 1.227 / 10 nm = <b>0.1227 nm = 1.227 &Aring; = 1.227 &times; 10<sup>-10</sup> m</b>.<br>This wavelength is comparable to interatomic spacing in crystals, enabling electron diffraction.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q44: A proton and an alpha particle are accelerated through the same potential difference V. Find the ratio of their de-Broglie wavelengths.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Formula: &lambda; = h / &radic;(2 m q V) &rArr; &lambda; &prop; 1 / &radic;(m q).<br>For proton: m<sub>p</sub> = m, q<sub>p</sub> = e.<br>For alpha particle: m<sub>&alpha;</sub> = 4m, q<sub>&alpha;</sub> = 2e.<br>&lambda;<sub>p</sub> / &lambda;<sub>&alpha;</sub> = &radic;[ (m<sub>&alpha;</sub> q<sub>&alpha;</sub>) / (m<sub>p</sub> q<sub>p</sub>) ] = &radic;[ (4m &times; 2e) / (m &times; e) ] = &radic;8 = <b>2 &radic;2 &approx; 2.828 : 1</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q45: A proton and a deuteron have the same de-Broglie wavelength. Find the ratio of (i) their velocities, (ii) their kinetic energies.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &lambda;<sub>p</sub> = &lambda;<sub>d</sub> &rArr; h/(m<sub>p</sub> v<sub>p</sub>) = h/(m<sub>d</sub> v<sub>d</sub>) &rArr; m<sub>p</sub> v<sub>p</sub> = m<sub>d</sub> v<sub>d</sub> (equal momenta).<br>Masses: m<sub>d</sub> = 2 m<sub>p</sub>.<br>(i) Velocity ratio: v<sub>p</sub> / v<sub>d</sub> = m<sub>d</sub> / m<sub>p</sub> = 2/1 &rArr; <b>v<sub>p</sub> : v<sub>d</sub> = 2 : 1</b>.<br>(ii) Kinetic energy ratio: K = p<sup>2</sup> / (2m) &rArr; K<sub>p</sub> / K<sub>d</sub> = m<sub>d</sub> / m<sub>p</sub> = <b>2 : 1</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q46: Explain why classical wave theory of light fails to explain: (i) existence of threshold frequency, (ii) instantaneous emission of photoelectrons.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      (i) <b>Threshold frequency failure:</b> Wave theory states light energy is proportional to intensity (amplitude squared). Thus, a high-intensity beam of any frequency should accumulate enough energy to eject electrons. But experimentally, no electrons emerge below &nu;<sub>0</sub>.<br>(ii) <b>Instantaneous emission failure:</b> Wave energy spreads uniformly across the entire wavefront. Calculating energy received per atom predicts a time delay of hours to days for an electron to accumulate work function energy. But emission occurs in &lt;10<sup>-9</sup> s.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q47: Draw a plot showing the variation of photoelectric current with collector plate potential for two different intensities of incident radiation having the same frequency. State your observations.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>Observations:</b><br>1. Both curves meet the negative potential axis at the <b>exact same stopping potential (-V<sub>0</sub>)</b> because incident frequency is identical.<br>2. The higher intensity curve reaches a <b>higher saturation current</b> (I<sub>sat</sub> &prop; Intensity) because a more intense light beam delivers more photons per second, ejecting more photoelectrons.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q48: Draw a plot of photoelectric current versus collector potential for two different frequencies &nu;_1 &gt; &nu;_2 of incident radiation having the same intensity. State your conclusions.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>Conclusions:</b><br>1. The curve for higher frequency &nu;<sub>1</sub> requires a <b>more negative stopping potential (-V<sub>01</sub> &gt; -V<sub>02</sub>)</b> because photoelectrons have higher maximum kinetic energy (K<sub>max</sub> = h&nu; - &Phi;<sub>0</sub>).<br>2. Both curves saturate at the <b>same saturation current</b> because identical intensity delivers the same total energy per second.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q49: In an experiment on photoelectric effect, the slope of the cut-off voltage versus frequency of incident light is found to be 4.12 x 10⁻¹⁵ V s. Calculate the value of Planck's constant.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: Slope = h / e = 4.12 &times; 10<sup>-15</sup> V s, e = 1.6 &times; 10<sup>-19</sup> C.<br>Planck's constant: <b>h = Slope &times; e = (4.12 &times; 10<sup>-15</sup>) &times; (1.6 &times; 10<sup>-19</sup>) = 6.592 &times; 10<sup>-34</sup> J s</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q50: Light of wavelength 4000 &Aring; is incident on a metal plate of work function 2.0 eV. Find: (i) energy of incident photon, (ii) maximum kinetic energy of emitted electron, (iii) stopping potential.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &lambda; = 4000 &Aring; = 4000 &times; 10<sup>-10</sup> m = 4 &times; 10<sup>-7</sup> m, &Phi;<sub>0</sub> = 2.0 eV.<br>(i) Photon energy: E = h c / &lambda; = (6.63 &times; 10<sup>-34</sup> &times; 3 &times; 10<sup>8</sup>) / (4 &times; 10<sup>-7</sup> &times; 1.6 &times; 10<sup>-19</sup>) eV = 1.989 / 0.64 eV = <b>3.108 eV &approx; 3.11 eV</b>.<br>(ii) Maximum kinetic energy: <b>K<sub>max</sub> = E - &Phi;<sub>0</sub> = 3.11 eV - 2.0 eV = 1.11 eV = 1.776 &times; 10<sup>-19</sup> J</b>.<br>(iii) Stopping potential: e V<sub>0</sub> = K<sub>max</sub> &rArr; <b>V<sub>0</sub> = 1.11 Volts</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q51: An electron and a photon each have a wavelength of 1.00 nm. Find: (i) their momenta, (ii) the energy of the photon, (iii) the kinetic energy of the electron.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &lambda; = 1.00 nm = 10<sup>-9</sup> m.<br>(i) Momentum (same for both by de-Broglie relation): <b>p = h / &lambda; = (6.63 &times; 10<sup>-34</sup>) / (10<sup>-9</sup>) = 6.63 &times; 10<sup>-25</sup> kg m s<sup>-1</sup></b>.<br>(ii) Photon energy: <b>E<sub>photon</sub> = h c / &lambda; = (6.63 &times; 10<sup>-34</sup> &times; 3 &times; 10<sup>8</sup>) / (10<sup>-9</sup> &times; 1.6 &times; 10<sup>-19</sup>) = 1243 eV = 1.243 keV</b>.<br>(iii) Electron kinetic energy: <b>K<sub>e</sub> = p<sup>2</sup> / (2 m<sub>e</sub>) = (6.63 &times; 10<sup>-25</sup>)<sup>2</sup> / [2 &times; (9.11 &times; 10<sup>-31</sup>) &times; 1.6 &times; 10<sup>-19</sup>] = 1.51 eV</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q52: Show that the de-Broglie wavelength of an electron accelerated through potential V volts is given by &lambda; = 1.227/&radic;V nm.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      An electron of charge e and mass m accelerated through potential difference V acquires kinetic energy: 1/2 m v<sup>2</sup> = e V &rArr; v = &radic;(2 e V / m).<br>Momentum: p = m v = &radic;(2 m e V).<br>de-Broglie wavelength: &lambda; = h / p = h / &radic;(2 m e V).<br>Substituting h = 6.63 &times; 10<sup>-34</sup> J s, m = 9.11 &times; 10<sup>-31</sup> kg, e = 1.6 &times; 10<sup>-19</sup> C:<br>&lambda; = (6.63 &times; 10<sup>-34</sup>) / &radic;[2 &times; 9.11 &times; 10<sup>-31</sup> &times; 1.6 &times; 10<sup>-19</sup> &times; V] = (1.227 &times; 10<sup>-9</sup>) / &radic;V m = <b>1.227 / &radic;V nm</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q53: State the properties of photons on which the quantum theory of radiation is based.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. Radiation interacts with matter in localized packets of energy called photons: <b>E = h&nu; = hc/&lambda;</b>.<br>2. Each photon carries momentum: <b>p = h/&lambda; = E/c</b>.<br>3. Photons travel with vacuum speed of light c and have <b>zero rest mass (m<sub>0</sub> = 0)</b>.<br>4. Photons are electrically neutral and unaffected by electric/magnetic fields.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q54: The work functions of three metals A, B, and C are 1.92 eV, 2.0 eV, and 5.0 eV respectively. Which of these metals will emit photoelectrons when illuminated by radiation of wavelength 412.5 nm?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Incident photon energy: E = h c / &lambda; = 12400 / 4125 eV = <b>3.006 eV &approx; 3.01 eV</b>.<br>Photoelectric emission occurs only if <b>E &ge; &Phi;<sub>0</sub></b>.<br>• Metal A (&Phi;<sub>0</sub> = 1.92 eV &lt; 3.01 eV) &rarr; <b>Emits photoelectrons</b>.<br>• Metal B (&Phi;<sub>0</sub> = 2.00 eV &lt; 3.01 eV) &rarr; <b>Emits photoelectrons</b>.<br>• Metal C (&Phi;<sub>0</sub> = 5.00 eV &gt; 3.01 eV) &rarr; <b>No emission</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q55: By what factor does the de-Broglie wavelength of a particle change if its kinetic energy is increased by 300%?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Initial kinetic energy = E. New kinetic energy E' = E + 300% of E = E + 3E = 4E.<br>Since &lambda; = h / &radic;(2mE) &prop; 1/&radic;E:<br>&lambda;' / &lambda; = &radic;(E / E') = &radic;(E / 4E) = &radic;(1/4) = 1/2.<br>&rArr; <b>&lambda;' = &lambda; / 2 (de-Broglie wavelength is halved)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q56: Why is an electron microscope preferred over an optical microscope for high magnification studies?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Resolving power is inversely proportional to wavelength (R.P. &prop; 1/&lambda;). An accelerated electron beam has a de-Broglie wavelength &lambda;<sub>e</sub> ~ 0.04 &Aring;, which is <b>~100,000 times shorter</b> than visible light (&lambda; ~ 5000 &Aring;), providing immense resolving power capable of imaging atomic crystal lattices.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q57: A source of light of power P = 20 W emits 4 x 10¹⁹ photons per second. Find the frequency and wavelength of the emitted light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Power P = N &times; E = N (h &nu;) &rArr; &nu; = P / (N h).<br>&nu; = 20 / (4 &times; 10<sup>19</sup> &times; 6.63 &times; 10<sup>-34</sup>) = 20 / (2.652 &times; 10<sup>-14</sup>) = <b>7.54 &times; 10<sup>14</sup> Hz</b>.<br>Wavelength: &lambda; = c / &nu; = (3 &times; 10<sup>8</sup>) / (7.54 &times; 10<sup>14</sup>) = <b>3.98 &times; 10<sup>-7</sup> m = 398 nm</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q58: Explain the term 'radiation pressure' in terms of photon theory for (i) total absorption, and (ii) total reflection.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      When photons strike a surface of area A at rate N photons per second:<br>(i) <b>Total Absorption:</b> Each photon transfers momentum p = E/c. Force F = &Delta;p/&Delta;t = (N E)/c = Power/c &rArr; <b>P<sub>rad</sub> = I / c</b>.<br>(ii) <b>Total Reflection:</b> Photons bounce back with momentum reversal &Delta;p = 2p = 2E/c &rArr; <b>P<sub>rad</sub> = 2 I / c</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q59: Calculate the ratio of de-Broglie wavelengths of a deuteron (mass 2m, charge e) and an alpha particle (mass 4m, charge 2e) moving with the same speed.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Formula: &lambda; = h / (m v). For equal velocity: &lambda; &prop; 1/m.<br>&lambda;<sub>d</sub> / &lambda;<sub>&alpha;</sub> = m<sub>&alpha;</sub> / m<sub>d</sub> = (4m) / (2m) = <b>2 / 1 = 2 : 1</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q60: Find the de-Broglie wavelength of a thermal neutron at temperature 27&deg;C (300 K).</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: T = 27 + 273 = 300 K, m<sub>n</sub> = 1.675 &times; 10<sup>-27</sup> kg, k<sub>B</sub> = 1.38 &times; 10<sup>-23</sup> J/K.<br>Formula: &lambda; = h / &radic;(3 m k<sub>B</sub> T).<br>&lambda; = (6.63 &times; 10<sup>-34</sup>) / &radic;[3 &times; (1.675 &times; 10<sup>-27</sup>) &times; (1.38 &times; 10<sup>-23</sup>) &times; 300] = (6.63 &times; 10<sup>-34</sup>) / &radic;[4.576 &times; 10<sup>-47</sup>] = (6.63 &times; 10<sup>-34</sup>) / (4.55 &times; 10<sup>-24</sup>) = <b>1.46 &times; 10<sup>-10</sup> m = 1.46 &Aring; = 0.146 nm</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q61: Why is ultraviolet light required to emit electrons from zinc while visible light can emit electrons from sodium?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Zinc has a high work function (&Phi;<sub>0</sub> &approx; 4.3 eV), so it requires high-energy UV photons (h&nu; &ge; 4.3 eV). Sodium has a low work function (&Phi;<sub>0</sub> &approx; 2.27 eV), which is easily overcome by visible light photons (E ~ 2.5 eV).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q62: Can photoelectric emission occur if the intensity of incident light is extremely large but frequency is less than threshold frequency? Explain.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> According to quantum theory, photoelectric emission is a one-to-one collision between a single photon and a single electron. If a photon's energy h&nu; is less than &Phi;<sub>0</sub>, it cannot liberate the electron, regardless of how many photons (intensity) strike the surface.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q63: How does the stopping potential depend on the distance between the light source and the photocell?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Stopping potential is <b>independent of distance</b>. Changing distance only alters light intensity (photocurrent), while photon frequency &nu; and energy remain constant.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q64: Define electron-volt (eV) and calculate its value in Joules.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      An electron-volt (eV) is the kinetic energy gained or lost by a single electron when accelerated through an electrostatic potential difference of one volt: <b>1 eV = q &times; V = (1.602 &times; 10<sup>-19</sup> C)(1 V) = 1.602 &times; 10<sup>-19</sup> Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q65: What is the significance of Davisson-Germer experiment in modern physics?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The Davisson-Germer experiment (1927) provided the first definitive experimental confirmation of de-Broglie's hypothesis by observing <b>diffraction of accelerated electron beams from a nickel crystal</b>, proving electrons behave as waves.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q66: Draw a schematic diagram of the experimental arrangement used to study the photoelectric effect.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The experimental setup consists of an evacuated quartz bulb enclosing a photosensitive cathode (C) and an anode collector (A), connected to a high-voltage variable DC supply with a commutator reversing switch, microammeter, and voltmeter.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q67: A metal surface is illuminated by light of frequency &nu;. If the threshold frequency is &nu;_0, write the equation relating maximum velocity v_max of emitted electrons with frequency.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      By Einstein's equation: 1/2 m v<sub>max</sub><sup>2</sup> = h (&nu; - &nu;<sub>0</sub>) &rArr; <span style='color: #76FF03;'><b>v<sub>max</sub> = &radic;[ ${frac('2 h (&nu; - &nu;<sub>0</sub>)', 'm')} ]</b></span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q68: If the frequency of incident radiation is doubled, will the maximum kinetic energy of emitted photoelectrons also be doubled? Explain.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No, it becomes more than double!</b><br>Initial: K<sub>1</sub> = h&nu; - &Phi;<sub>0</sub>. When frequency is doubled (2&nu;): K<sub>2</sub> = 2h&nu; - &Phi;<sub>0</sub> = 2(h&nu; - &Phi;<sub>0</sub>) + &Phi;<sub>0</sub> = <b>2 K<sub>1</sub> + &Phi;<sub>0</sub> &gt; 2 K<sub>1</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q69: Why is a photo-cell also called an 'electric eye'?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A photocell instantly converts incident light photons into an electric current, mimicking the visual sensing action of an eye. It is widely used in automatic streetlights, burglar alarms, and door sensors.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q70: What are the three main types of photoelectric cells?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. <b>Photo-emissive cell:</b> Operates via emission of photoelectrons into vacuum.<br>2. <b>Photo-voltaic cell:</b> Generates an EMF across a p-n junction under illumination (solar cells).<br>3. <b>Photo-conductive cell:</b> Electrical resistance decreases upon illumination (LDR).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q71: An electron, an alpha-particle, and a proton have the same kinetic energy. Which one has the shortest de-Broglie wavelength?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Since &lambda; = h / &radic;(2mE), for equal kinetic energy: &lambda; &prop; 1/&radic;m.<br>Since alpha particle has the largest mass (m<sub>&alpha;</sub> &approx; 4 m<sub>p</sub> &approx; 7344 m<sub>e</sub>), the <b>alpha-particle has the shortest de-Broglie wavelength</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q72: A particle is moving in a straight line with constant momentum p. What is the phase velocity of its matter wave?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Phase velocity v<sub>p</sub> = &omega;/k = E/p = (m c<sup>2</sup>)/(m v) = <b>c<sup>2</sup> / v &gt; c</b>. (Note: The group velocity v<sub>g</sub> = d&omega;/dk = v equals the physical particle speed and does not exceed c).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q73: Explain why we do not observe quantum diffraction effects when a person walks through a normal doorway.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A person of mass m = 70 kg walking at v = 1.5 m/s has momentum p = 105 kg m/s. Their de-Broglie wavelength is &lambda; = (6.63 &times; 10<sup>-34</sup>)/105 &approx; 6.3 &times; 10<sup>-36</sup> m. A doorway has width a ~ 1 m. Since &lambda; &lt;&lt; a by 36 orders of magnitude, diffraction is totally nonexistent.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q74: Light of frequency 1.5 times the threshold frequency is incident on a photosensitive material. If frequency is halved and intensity is doubled, what will be the new photoelectric current?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      New frequency: &nu;' = (1.5 &nu;<sub>0</sub>)/2 = <b>0.75 &nu;<sub>0</sub></b>.<br>Since new frequency is strictly less than threshold frequency (&nu;' &lt; &nu;<sub>0</sub>), <b>no photoelectric emission occurs and photocurrent becomes exactly ZERO</b>, regardless of doubling intensity!\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q75: State two factors on which the work function of a metal depends.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. Nature and chemical purity of the metal substrate.<br>2. Surface condition, roughness, and cleanliness of the metal.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q76: Can X-rays produce photoelectric emission from metals? Explain.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>Yes!</b> X-rays have very high frequencies (&nu; ~ 10<sup>16</sup> - 10<sup>19</sup> Hz) and photon energies (hundreds of eV to keV), which easily exceed metal work functions (~2 - 5 eV), ejecting high-speed photoelectrons.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q77: Why is vacuum necessary inside a photoelectric tube?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      An evacuated tube ensures emitted photoelectrons travel freely from cathode to anode without colliding with or getting scattered by atmospheric gas molecules.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q78: Write the expression for the de-Broglie wavelength of an uncharged neutron of mass m possessing kinetic energy E.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The expression is: <b>&lambda; = h / &radic;(2 m E)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q79: Explain why cathode rays can produce X-rays when striking a heavy metal target.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      When fast-moving electrons in cathode rays suddenly decelerate upon striking high-Z metal target atoms, their loss of kinetic energy is radiated away as high-energy continuous and characteristic X-ray photons (Bremsstrahlung radiation).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q80: What did Millikan's photoelectric experiment achieve?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Robert Millikan (1916) experimentally validated Einstein's photoelectric linear relation V<sub>0</sub> = (h/e)&nu; - &Phi;<sub>0</sub>/e with high precision, obtaining the first accurate experimental measurement of <b>Planck's constant (h)</b> and winning the Nobel Prize in 1923.\n    </div>\n  </div>\n<h2 style=\"color: #E040FB; border-bottom: 2px solid #E040FB; padding-bottom: 6px; margin-top: 35px;\">SECTION C: Long Answer (LA) Questions (5 Marks Each &bull; Q81 to Q100)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q81: State Einstein's photoelectric equation. Explain with detailed physical reasoning how this equation successfully accounts for all the experimental laws of photoelectric emission.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Einstein's Photoelectric Equation:</b><br>\n      Einstein postulated that light consists of discrete photons of energy E = h&nu;. When a photon is absorbed by an electron, energy conservation gives:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>K<sub>max</sub> = h &nu; - &Phi;<sub>0</sub> = h (&nu; - &nu;<sub>0</sub>) = e V<sub>0</sub></b></span>.<br>\n      <b>2. Explanation of All 4 Experimental Laws:</b><br>\n      • <b>Explanation of Law 1 (Photocurrent &prop; Intensity):</b> Intensity of light is proportional to the number of photons incident per unit area per second. Since each emitted electron results from a 1:1 collision with a photon, increasing intensity increases number of emitted photoelectrons and photocurrent proportionally.<br>\n      • <b>Explanation of Law 2 (K<sub>max</sub> &prop; &nu; &amp; independent of Intensity):</b> From K<sub>max</sub> = h&nu; - &Phi;<sub>0</sub>, maximum kinetic energy depends strictly linearly on incident frequency &nu;. Increasing intensity only increases photon count, not individual photon energy.<br>\n      • <b>Explanation of Law 3 (Existence of Threshold Frequency &nu;<sub>0</sub>):</b> For K<sub>max</sub> &ge; 0, we must have h&nu; &ge; &Phi;<sub>0</sub> &rArr; &nu; &ge; &Phi;<sub>0</sub>/h = &nu;<sub>0</sub>. If incident frequency &nu; &lt; &nu;<sub>0</sub>, K<sub>max</sub> would be negative (physically impossible), so no emission occurs regardless of intensity.<br>\n      • <b>Explanation of Law 4 (Instantaneous Emission):</b> The interaction is an instantaneous quantum collision between a single photon and a conduction electron. Energy transfer occurs in a single quantum step (&Delta;t &lt; 10<sup>-9</sup> s) without cumulative delay.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q82: Describe the experimental study of photoelectric effect with a neat circuit diagram. Explain the effects of: (i) Intensity on photocurrent, (ii) Potential on photocurrent and stopping potential, (iii) Frequency on stopping potential.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Experimental Setup:</b> Consists of an evacuated glass/quartz tube containing photosensitive cathode C and anode collector A, connected to a commutator, microammeter, voltmeter, and variable DC battery supply.<br>\n      <b>2. Three Experimental Investigations:</b><br>\n      • <b>(i) Effect of Intensity:</b> Keeping &nu; (&gt; &nu;<sub>0</sub>) and accelerating potential constant, photocurrent increases linearly with incident light intensity. Graph is a straight line through origin.<br>\n      • <b>(ii) Effect of Potential:</b> When positive potential of A increases, current rises to Saturation Current (I<sub>sat</sub>). When A is made negative, current drops to zero at Stopping Potential (-V<sub>0</sub>). Higher intensity yields higher saturation current but the <b>exact same stopping potential</b>.<br>\n      • <b>(iii) Effect of Frequency:</b> For different frequencies &nu;<sub>1</sub> &gt; &nu;<sub>2</sub> &gt; &nu;<sub>3</sub> at constant intensity, higher frequency requires higher negative stopping potential (|V<sub>01</sub>| &gt; |V<sub>02</sub>| &gt; |V<sub>03</sub>|). Plot of V<sub>0</sub> vs &nu; is a straight line with universal slope h/e and X-intercept &nu;<sub>0</sub>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q83: Derive the de-Broglie wavelength for (i) a material particle of mass m and velocity v, (ii) a particle with kinetic energy E, (iii) a charged particle q accelerated through potential V.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Basic Formulation:</b><br>\n      For a photon: E = h &nu; = h c / &lambda; and E = m c<sup>2</sup>.<br>\n      Equating: m c<sup>2</sup> = h c / &lambda; &rArr; &lambda; = h / (m c) = h / p.<br>\n      By de-Broglie hypothesis, extending to any material particle moving with speed v:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">p</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">m v</span></span></b></span>.<br>\n      <b>2. In Terms of Kinetic Energy E:</b><br>\n      Kinetic energy E = p<sup>2</sup> / (2m) &rArr; p = &radic;(2 m E).<br>\n      <span style=\"color: #00E5FF; font-family: monospace; font-size: 17px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;(2 m E)</span></span></b></span>.<br>\n      <b>3. For Charged Particle Accelerated Through Potential V:</b><br>\n      Work done by electric field: E = q V.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b>&lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;(2 m q V)</span></span></b></span>.<br>\n      <b>Special Case (Electron):</b> Substituting m<sub>e</sub> = 9.11 &times; 10<sup>-31</sup> kg, q = e = 1.6 &times; 10<sup>-19</sup> C, h = 6.63 &times; 10<sup>-34</sup> J s gives:<br>\n      <b>&lambda;<sub>e</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1.227</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;V</span></span> nm = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">12.27</span><span style=\"padding: 0 2px; display: inline-block;\">&radic;V</span></span> &Aring;</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q84: Discuss the failure of classical wave theory to explain the photoelectric effect and how Planck's quantum hypothesis provided the revolutionary breakthrough.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Three Failures of Classical Wave Theory:</b><br>\n      • <i>Intensity vs Kinetic Energy:</i> Wave theory dictates wave energy is proportional to amplitude squared (intensity). Thus, brighter light should eject more energetic electrons. Experimentally, electron energy depends only on frequency &nu; and is independent of intensity.<br>\n      • <i>Threshold Frequency:</i> Classical waves transfer energy continuously; light of any frequency should eventually eject electrons if illuminated long enough. Experimentally, no emission occurs below &nu;<sub>0</sub>.<br>\n      • <i>Time Delay:</i> Classical wave fronts spread energy across millions of surface atoms. Energy absorbed per electron atom is tiny (~10<sup>-12</sup> eV/s), predicting a delay of days before ejection. Experimentally, emission occurs in &lt;10<sup>-9</sup> s.<br>\n      <b>2. Planck &amp; Einstein's Quantum Breakthrough:</b><br>\n      Einstein resolved all three contradictions by adopting Planck's quantum hypothesis: light is absorbed in indivisible bundles (photons) of energy E = h&nu;. In a 1:1 collision, the electron gets the entire photon energy instantaneously.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q85: Explain the variation of stopping potential with frequency of incident radiation. How is this relation used to determine Planck's constant and work function of a metal?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Mathematical Relation:</b><br>\n      Einstein's equation: e V<sub>0</sub> = h &nu; - &Phi;<sub>0</sub> &rArr; <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>V<sub>0</sub> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">e</span></span>) &nu; - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&Phi;<sub>0</sub></span><span style=\"padding: 0 2px; display: inline-block;\">e</span></span></b></span>.<br>\n      Comparing with straight-line equation: y = m x + c.<br>\n      <b>2. Graphical Plot:</b><br>\n      A plot of Stopping Potential (V<sub>0</sub>) on y-axis against Frequency (&nu;) on x-axis is a straight line.<br>\n      <b>3. Determination of Planck's Constant (h):</b><br>\n      • Measure slope of line: Slope = &Delta;V<sub>0</sub> / &Delta;&nu;.<br>\n      • Planck's constant is calculated as: <b>h = e &times; Slope</b>.<br>\n      <b>4. Determination of Work Function (&Phi;<sub>0</sub>):</b><br>\n      • The X-intercept on frequency axis gives threshold frequency &nu;<sub>0</sub> &rArr; <b>&Phi;<sub>0</sub> = h &nu;<sub>0</sub></b>.<br>\n      • The negative Y-intercept equals -&Phi;<sub>0</sub>/e &rArr; <b>&Phi;<sub>0</sub> = e &times; |Y-intercept|</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q86: Light of wavelength 2000 &Aring; falls on an aluminum surface (work function 4.2 eV). Calculate: (a) kinetic energy of fastest and slowest emitted photoelectrons, (b) stopping potential, (c) cut-off wavelength for aluminum.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Given: &lambda; = 2000 &Aring; = 2 &times; 10<sup>-7</sup> m, &Phi;<sub>0</sub> = 4.2 eV.<br>\n      <b>(a) Energy of Incident Photon:</b><br>\n      E = h c / &lambda; = (6.63 &times; 10<sup>-34</sup> &times; 3 &times; 10<sup>8</sup>) / (2 &times; 10<sup>-7</sup> &times; 1.6 &times; 10<sup>-19</sup>) eV = 1.989 / 0.32 eV = <b>6.216 eV &approx; 6.22 eV</b>.<br>\n      • Fastest Photoelectrons: <b>K<sub>max</sub> = E - &Phi;<sub>0</sub> = 6.22 eV - 4.20 eV = 2.02 eV = 3.232 &times; 10<sup>-19</sup> J</b>.<br>\n      • Slowest Photoelectrons: <b>K<sub>min</sub> = 0 eV</b> (electrons losing all excess energy in internal collisions).<br>\n      <b>(b) Stopping Potential:</b> e V<sub>0</sub> = K<sub>max</sub> &rArr; <b>V<sub>0</sub> = 2.02 Volts</b>.<br>\n      <b>(c) Cut-off (Threshold) Wavelength:</b><br>\n      &lambda;<sub>0</sub> = h c / &Phi;<sub>0</sub> = (1.989 &times; 10<sup>-25</sup> J m) / (4.2 &times; 1.6 &times; 10<sup>-19</sup> J) = <b>2.96 &times; 10<sup>-7</sup> m = 296 nm = 2960 &Aring;</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q87: A particle of mass m is confined in a one-dimensional box. Explain how de-Broglie's concept of standing matter waves naturally explains Bohr's postulate of angular momentum quantization.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. de-Broglie's Explanation of Bohr's Quantization:</b><br>\n      de-Broglie argued that an electron in a stable Bohr atomic orbit behaves as a circular stationary (standing) matter wave.<br>\n      <b>2. Condition for Standing Wave on Circular Orbit:</b><br>\n      To prevent destructive self-interference, the circumference of the n<sup>th</sup> orbit must be an integral multiple of de-Broglie wavelength &lambda;:<br>\n      <span style=\"color: #00E5FF; font-family: monospace; font-size: 16.5px;\"><b>2 &pi; r<sub>n</sub> = n &lambda;</b></span> &nbsp;&nbsp; (n = 1, 2, 3, ...).<br>\n      <b>3. Substituting de-Broglie Formula &lambda; = h / p = h / (m v):</b><br>\n      2 &pi; r<sub>n</sub> = n (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">m v<sub>n</sub></span></span>) &rArr; m v<sub>n</sub> r<sub>n</sub> = n (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">2 &pi;</span></span>).<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b>L = m v r = n <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">2 &pi;</span></span></b></span>.<br>\n      This beautifully derives Bohr's quantum postulate (L = n &hbar;) from wave mechanics!\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q88: In an experiment on photoelectric effect, light of wavelengths 400 nm and 300 nm produce stopping potentials 1.10 V and 2.13 V respectively. Calculate: (i) Planck's constant, (ii) work function of metal, (iii) threshold wavelength.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Given: &lambda;<sub>1</sub> = 400 &times; 10<sup>-9</sup> m, V<sub>01</sub> = 1.10 V; &lambda;<sub>2</sub> = 300 &times; 10<sup>-9</sup> m, V<sub>02</sub> = 2.13 V.<br>\n      Einstein's equations: e V<sub>01</sub> = h c / &lambda;<sub>1</sub> - &Phi;<sub>0</sub>, &nbsp; e V<sub>02</sub> = h c / &lambda;<sub>2</sub> - &Phi;<sub>0</sub>.<br>\n      Subtracting: e (V<sub>02</sub> - V<sub>01</sub>) = h c [ 1/&lambda;<sub>2</sub> - 1/&lambda;<sub>1</sub> ].<br>\n      (1.6 &times; 10<sup>-19</sup>)(2.13 - 1.10) = h (3 &times; 10<sup>8</sup>) [ 1/(300 &times; 10<sup>-9</sup>) - 1/(400 &times; 10<sup>-9</sup>) ].<br>\n      (1.6 &times; 10<sup>-19</sup>)(1.03) = h (3 &times; 10<sup>8</sup>) &times; [ (4 - 3)/1200 &times; 10<sup>-9</sup> ] = h (3 &times; 10<sup>8</sup>)(10<sup>9</sup> / 1200) = h (2.5 &times; 10<sup>14</sup>).<br>\n      <b>(i) Planck's constant:</b> <b>h = (1.648 &times; 10<sup>-19</sup>) / (2.5 &times; 10<sup>14</sup>) = 6.592 &times; 10<sup>-34</sup> J s</b>.<br>\n      <b>(ii) Work Function:</b> &Phi;<sub>0</sub> = h c / &lambda;<sub>1</sub> - e V<sub>01</sub> = [ (6.592 &times; 10<sup>-34</sup> &times; 3 &times; 10<sup>8</sup>)/(400 &times; 10<sup>-9</sup> &times; 1.6 &times; 10<sup>-19</sup>) ] - 1.10 = 3.09 eV - 1.10 eV = <b>1.99 eV</b>.<br>\n      <b>(iii) Threshold Wavelength:</b> &lambda;<sub>0</sub> = h c / &Phi;<sub>0</sub> = 1240 eV nm / 1.99 eV = <b>623 nm = 6230 &Aring;</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q89: Explain the concept of matter waves. Compare the properties of matter waves with electromagnetic waves across five distinct criteria.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Nature of Matter Waves:</b> Matter waves are probability waves associated with any moving material particle representing the probability density (&psi;<sup>2</sup>) of locating the particle in space.<br>\n      <b>2. Detailed Comparison Matrix:</b><br>\n      • <i>Origin:</i> EM waves are produced by accelerating electric charges; Matter waves are associated with any moving mass (neutral or charged).<br>\n      • <i>Speed:</i> EM waves travel at constant speed c = 3 &times; 10<sup>8</sup> m/s in vacuum; Matter waves travel with particle velocity v (&lt; c).<br>\n      • <i>Fields:</i> EM waves consist of oscillating electric &vec;E and magnetic &vec;B fields; Matter waves do not consist of physical electromagnetic fields.<br>\n      • <i>Wavelength:</i> EM wave &lambda; = c/&nu;; Matter wave &lambda; = h/(mv).<br>\n      • <i>Radiation:</i> EM waves can radiate into empty space; Matter waves are bound to the moving particle.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q90: A beam of monochromatic light of intensity I = 100 W/m2 falls normally on a totally reflecting plate of area A = 20 cm2. Calculate: (a) radiation pressure, (b) total force exerted on the plate, (c) number of photons striking per second if wavelength is 500 nm.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Given: I = 100 W/m<sup>2</sup>, A = 20 cm<sup>2</sup> = 20 &times; 10<sup>-4</sup> m<sup>2</sup> = 2 &times; 10<sup>-3</sup> m<sup>2</sup>, &lambda; = 500 nm = 5 &times; 10<sup>-7</sup> m, Total reflection.<br>\n      <b>(a) Radiation Pressure:</b><br>\n      For total reflection: <b>P<sub>rad</sub> = 2 I / c = (2 &times; 100) / (3 &times; 10<sup>8</sup>) = 6.67 &times; 10<sup>-7</sup> N/m<sup>2</sup> (Pa)</b>.<br>\n      <b>(b) Total Force Exerted:</b><br>\n      <b>F = P<sub>rad</sub> &times; A = (6.67 &times; 10<sup>-7</sup>) &times; (2 &times; 10<sup>-3</sup>) = 1.33 &times; 10<sup>-9</sup> N</b>.<br>\n      <b>(c) Number of Photons Striking per Second (N):</b><br>\n      Total power incident: P = I &times; A = 100 &times; (2 &times; 10<sup>-3</sup>) = 0.20 W.<br>\n      Energy per photon: E = h c / &lambda; = (6.63 &times; 10<sup>-34</sup> &times; 3 &times; 10<sup>8</sup>) / (5 &times; 10<sup>-7</sup>) = 3.978 &times; 10<sup>-19</sup> J.<br>\n      <b>N = P / E = 0.20 / (3.978 &times; 10<sup>-19</sup>) = 5.03 &times; 10<sup>17</sup> photons/second</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q91: State the two laws of conservation that apply to photon-electron collisions in the Compton effect and Photoelectric effect. Explain why Compton scattering cannot occur with tightly bound inner electrons.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Fundamental Conservation Laws:</b><br>\n      • <b>Law of Conservation of Total Energy:</b> E<sub>photon</sub> + E<sub>electron</sub> = const.<br>\n      • <b>Law of Conservation of Total Linear Momentum:</b> &vec;p<sub>photon</sub> + &vec;p<sub>electron</sub> = const.<br>\n      <b>2. Compton Effect with Free vs Bound Electrons:</b><br>\n      • In Compton scattering, an incident X-ray photon collides with an essentially <i>free / loosely bound outer electron</i>, transferring part of its momentum and scattering with longer wavelength &Delta;&lambda; = (h/m<sub>e</sub>c)(1 - cos &theta;).<br>\n      • If the electron is <i>tightly bound to the nucleus</i>, the entire atom (mass M &gt;&gt; m<sub>e</sub>) absorbs the collision momentum. Since Compton shift &Delta;&lambda; &prop; 1/M &approx; 0, the photon scatters without wavelength shift (unmodified Rayleigh scattering).\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q92: Two identical metal plates A and B are illuminated with light of frequencies &nu;_A and &nu;_B (&nu;_A = 2 &nu;_B). If the maximum kinetic energy of photoelectrons from A is three times that from B, find the work function of the metal in terms of &nu;_B.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Given: &nu;<sub>A</sub> = 2 &nu;<sub>B</sub>, K<sub>A</sub> = 3 K<sub>B</sub>.<br>\n      Einstein's equations:<br>\n      K<sub>A</sub> = h &nu;<sub>A</sub> - &Phi;<sub>0</sub> = 2 h &nu;<sub>B</sub> - &Phi;<sub>0</sub>. &nbsp;&nbsp; ...(1)<br>\n      K<sub>B</sub> = h &nu;<sub>B</sub> - &Phi;<sub>0</sub>. &nbsp;&nbsp; ...(2)<br>\n      Substituting (1) and (2) into K<sub>A</sub> = 3 K<sub>B</sub>:<br>\n      2 h &nu;<sub>B</sub> - &Phi;<sub>0</sub> = 3 (h &nu;<sub>B</sub> - &Phi;<sub>0</sub>) = 3 h &nu;<sub>B</sub> - 3 &Phi;<sub>0</sub>.<br>\n      3 &Phi;<sub>0</sub> - &Phi;<sub>0</sub> = 3 h &nu;<sub>B</sub> - 2 h &nu;<sub>B</sub>.<br>\n      2 &Phi;<sub>0</sub> = h &nu;<sub>B</sub> &rArr; <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>&Phi;<sub>0</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">2</span></span> h &nu;<sub>B</sub> = 0.5 h &nu;<sub>B</sub></b></span>.<br>\n      Threshold frequency: &nu;<sub>0</sub> = &Phi;<sub>0</sub>/h = 0.5 &nu;<sub>B</sub>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q93: Explain how the wave nature of matter leads to the concept of electron diffraction and describe the experimental verification by G.P. Thomson.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Wave Nature &amp; Diffraction Concept:</b><br>\n      de-Broglie predicted that electrons accelerated to hundreds of volts have wavelengths &lambda; ~ 1 &Aring;, which matches the atomic lattice spacing d of crystals. Thus, crystal planes act as a 3D diffraction grating.<br>\n      <b>2. G.P. Thomson's Gold Foil Experiment (1928):</b><br>\n      • Thomson directed a narrow beam of high-speed cathode electrons (~50 kV) through an ultra-thin gold foil (~10<sup>-8</sup> m thick).<br>\n      • A photographic plate placed behind the foil revealed a series of concentric circular diffraction rings, identical to X-ray powder diffraction patterns.<br>\n      • The observed ring diameters matched Bragg's diffraction law 2d sin &theta; = n&lambda; using de-Broglie's wavelength &lambda; = h/p, definitively proving the wave nature of electrons.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q94: Find the ratio of de-Broglie wavelengths of a proton and an alpha particle when they have: (a) the same velocity, (b) the same kinetic energy, (c) accelerated through the same potential difference.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Masses: m<sub>p</sub> = m, m<sub>&alpha;</sub> = 4m; Charges: q<sub>p</sub> = e, q<sub>&alpha;</sub> = 2e.<br>\n      <b>(a) Same Velocity:</b> &lambda; = h / (m v) &rArr; &lambda;<sub>p</sub> / &lambda;<sub>&alpha;</sub> = m<sub>&alpha;</sub> / m<sub>p</sub> = 4m / m = <b>4 : 1</b>.<br>\n      <b>(b) Same Kinetic Energy:</b> &lambda; = h / &radic;(2mE) &rArr; &lambda;<sub>p</sub> / &lambda;<sub>&alpha;</sub> = &radic;(m<sub>&alpha;</sub> / m<sub>p</sub>) = &radic;(4m / m) = &radic;4 = <b>2 : 1</b>.<br>\n      <b>(c) Same Accelerating Potential V:</b> &lambda; = h / &radic;(2mqV) &rArr; &lambda;<sub>p</sub> / &lambda;<sub>&alpha;</sub> = &radic;[ (m<sub>&alpha;</sub> q<sub>&alpha;</sub>) / (m<sub>p</sub> q<sub>p</sub>) ] = &radic;[ (4m &times; 2e) / (m &times; e) ] = &radic;8 = <b>2 &radic;2 : 1 &approx; 2.828 : 1</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q95: Explain why photoelectric current saturates at a finite value as accelerating potential is increased. Why does it not increase indefinitely?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Physical Mechanism:</b><br>\n      • For a fixed intensity and frequency of incident light, a fixed number of photons strike the photosensitive cathode per second, liberating a finite, constant number of photoelectrons per second: n = dN/dt.<br>\n      • When the accelerating potential on anode A is small, some slower electrons are deflected by space charge and fail to reach A.<br>\n      • As potential is increased, more electrons are pulled to A. At saturation potential V<sub>sat</sub>, <b>100% of emitted photoelectrons are collected by anode A per second</b>.<br>\n      • Increasing potential beyond this value cannot produce more current because no additional electrons are available from cathode (I<sub>sat</sub> = n e = const).\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q96: Derive the expression for the minimum wavelength &lambda;_min (Duane-Hunt limit) of continuous X-rays produced in an X-ray tube operating at voltage V.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Mechanism of Continuous X-Ray Production:</b><br>\n      When an electron accelerated through potential V strikes a heavy metal target, its total kinetic energy E = e V is converted into a single X-ray photon in a direct deceleration collision.<br>\n      <b>2. Mathematical Formulation:</b><br>\n      Conservation of energy gives:<br>\n      h &nu;<sub>max</sub> = e V &rArr; h (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">c</span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;<sub>min</sub></span></span>) = e V.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b>&lambda;<sub>min</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h c</span><span style=\"padding: 0 2px; display: inline-block;\">e V</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">12400</span><span style=\"padding: 0 2px; display: inline-block;\">V(volts)</span></span> &Aring; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1240</span><span style=\"padding: 0 2px; display: inline-block;\">V(volts)</span></span> nm</b></span>.<br>\n      This cut-off wavelength &lambda;<sub>min</sub> (Duane-Hunt limit) depends strictly on accelerating voltage V and is completely independent of the target material!\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q97: A photon of frequency &nu; collides with an electron at rest. Show that the wavelength shift &Delta;&lambda; in Compton scattering depends only on the scattering angle &theta;.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Energy and Momentum Conservation:</b><br>\n      Let incident photon have energy h&nu; and momentum h&nu;/c along x-axis. After scattering at angle &theta;, photon has energy h&nu;' and electron recoils at angle &phi; with relativistic momentum p<sub>e</sub>.<br>\n      • Energy Conservation: h&nu; + m<sub>0</sub>c<sup>2</sup> = h&nu;' + &radic;(p<sub>e</sub><sup>2</sup>c<sup>2</sup> + m<sub>0</sub><sup>2</sup>c<sup>4</sup>).<br>\n      • X-Momentum: (h&nu;/c) = (h&nu;'/c) cos &theta; + p<sub>e</sub> cos &phi;.<br>\n      • Y-Momentum: 0 = (h&nu;'/c) sin &theta; - p<sub>e</sub> sin &phi;.<br>\n      <b>2. Algebraic Reduction:</b> Squaring and subtracting yields:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>&Delta;&lambda; = &lambda;' - &lambda; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h</span><span style=\"padding: 0 2px; display: inline-block;\">m<sub>0</sub> c</span></span> (1 - cos &theta;) = &lambda;<sub>c</sub> (1 - cos &theta;)</b></span>,<br>\n      where &lambda;<sub>c</sub> = h/(m<sub>0</sub>c) = 0.0243 &Aring; is the <b>Compton Wavelength</b> of the electron. The shift depends purely on scattering angle &theta;.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q98: In an experiment on photoelectric effect, the graph between maximum kinetic energy K_max and frequency &nu; for two metals X and Y are parallel straight lines. (i) Which metal has higher work function? (ii) What does the slope indicate? (iii) If both are illuminated by light of same frequency, from which metal will electrons have higher kinetic energy?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. (i) Higher Work Function:</b> Metal Y whose line is shifted further to the right on the frequency axis has a higher threshold frequency (&nu;<sub>0Y</sub> &gt; &nu;<sub>0X</sub>) and therefore a <b>higher work function (&Phi;<sub>0Y</sub> &gt; &Phi;<sub>0X</sub>)</b>.<br>\n      <b>2. (ii) Meaning of Slope:</b> The slope of both parallel lines equals <b>Planck's constant (h)</b>: Slope = &Delta;K<sub>max</sub> / &Delta;&nu; = h.<br>\n      <b>3. (iii) Higher Kinetic Energy:</b> From K<sub>max</sub> = h&nu; - &Phi;<sub>0</sub>, since &Phi;<sub>0X</sub> &lt; &Phi;<sub>0Y</sub>, photoelectrons emitted from <b>Metal X will have higher kinetic energy</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q99: Calculate the de-Broglie wavelength of an &alpha;-particle accelerated through a potential difference of 200 V (m_&alpha; = 6.64 x 10⁻²⁷ kg, q_&alpha; = 3.2 x 10⁻¹⁹ C).</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Given: V = 200 Volts, m<sub>&alpha;</sub> = 6.64 &times; 10<sup>-27</sup> kg, q<sub>&alpha;</sub> = 3.2 &times; 10<sup>-19</sup> C, h = 6.63 &times; 10<sup>-34</sup> J s.<br>\n      Formula: &lambda;<sub>&alpha;</sub> = h / &radic;(2 m<sub>&alpha;</sub> q<sub>&alpha;</sub> V).<br>\n      Denominator = &radic;[2 &times; (6.64 &times; 10<sup>-27</sup>) &times; (3.2 &times; 10<sup>-19</sup>) &times; 200] = &radic;[8.4992 &times; 10<sup>-43</sup>] = &radic;[84.992 &times; 10<sup>-44</sup>] = 9.219 &times; 10<sup>-22</sup> kg m s<sup>-1</sup>.<br>\n      &lambda;<sub>&alpha;</sub> = (6.63 &times; 10<sup>-34</sup>) / (9.219 &times; 10<sup>-22</sup>) = <b>7.19 &times; 10<sup>-13</sup> m = 0.000719 nm = 0.00719 &Aring;</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(224, 64, 251, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #E040FB; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q100: Explain how the particle nature of light is verified by Arthur Compton's discovery of Compton scattering.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Phenomenon:</b> In 1923, Arthur Compton directed monochromatic X-rays at a graphite target and discovered that scattered X-rays contained a longer wavelength component (&lambda;' &gt; &lambda;) in addition to the incident wavelength.<br>\n      <b>2. Quantum Particle Treatment:</b><br>\n      Compton treated the interaction as a relativistic elastic billiard-ball collision between a single X-ray photon (E = h&nu;, p = h/&lambda;) and a stationary electron.<br>\n      The photon transfers part of its energy and momentum to the recoiling electron, emerging with reduced frequency &nu;' and longer wavelength &lambda;' = &lambda; + (h/m<sub>e</sub>c)(1 - cos &theta;).<br>\n      <b>3. Historic Impact:</b> The exact match between theory and experiment provided undeniable, direct proof of the particle nature of light and earned Compton the Nobel Prize in 1927.\n    \n    </div>\n  </div>\n</div>";

